do $$ declare definition text; begin select pg_get_functiondef('public.convert_pre_budget_to_budget(uuid,uuid)'::regprocedure) into definition; if position('target.status<>''draft''' in definition)=0 then raise exception 'Unexpected conversion function'; end if; definition:=replace(definition,'target.status<>''draft''','target.status not in (''draft'',''sent'')'); definition:=replace(definition,'Only draft pre-budgets can be converted','Only draft or sent pre-budgets can be converted'); definition:=replace(definition,'set number=next_number,document_type=''budget''','set status=''draft'',number=next_number,document_type=''budget'''); execute definition; end $$;